<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserPersonalApiKey\Infrastructure\Driver\Rest;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use OpenApi\Attributes as OA;
use Throwable;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Shared\Infrastructure\Sql\SqlTemplate;
use Civi\Lughauth\Shared\Infrastructure\LongTask\Runner;
use Civi\Lughauth\Shared\Infrastructure\LongTask\TaskKey;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Application\Usecase\Delete\UserPersonalApiKeyDeleteUsecase;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Domain\Gateway\UserPersonalApiKeyFilter;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Infrastructure\Driver\Batch\UserPersonalApiKeyTaskDelete;
use Civi\Lughauth\Features\Access\User\Domain\UserRef;

class UserPersonalApiKeyDeleteController
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly SqlTemplate $sql,
        private readonly Runner $runner,
        private readonly UserPersonalApiKeyDeleteUsecase $deleteUsecase,
    ) {
    }
    #[OA\Delete(
        path: "/api/access/me/api-keys/{uid}",
        tags: ["User personal api key"],
        description: "Delete the record",
        parameters: [
        new OA\PathParameter(name: "uid", required: true, schema: new OA\Schema(type: "string")),
    ],
        responses: [
        new OA\Response(response: 200, description: "Ok", content: new OA\JsonContent(type: "object", ref:"#/components/schemas/UserPersonalApiKeyApiDTO")),
        new OA\Response(response: 404, description: "Not found"),
    ]
    )
    ]
    public function delete(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("Delete User personal api key");
        $span = $this->startSpan("Delete User personal api key");
        $this->sql->begin();
        try {
            if (!isset($args['uid'])) {
                throw new NotFoundException('-');
            }
            $uid = $args['uid'];
            $this->deleteUsecase->delete($uid);
            $this->sql->commit();
            return $response->withStatus(204)
              ->withHeader('Content-Type', 'application/json');
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $this->sql->close();
            ;
            $span->end();
        }
    }
    public function deleteAllForQuery(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("Delete all for query User personal api key");
        $span = $this->startSpan("Delete all for query User personal api key");
        try {
            $params = $request->getQueryParams();
            $filter = new UserPersonalApiKeyFilter(
                uids: isset($params['uid']) ? [$params['uid']] : (isset($params['uids']) ? explode(',', $params['uids']) : null),
                search: $params['search'] ?? null,
                keyHash: $params['key-hash'] ?? null,
                user: isset($params['user']) ? new UserRef($params['user']) : null,
                name: $params['name'] ?? null,
            );
            $res = $this->runner->run(UserPersonalApiKeyTaskDelete::class, ['filter' => $filter]);
            $encoded = json_encode($res);
            $response->getBody()->write($encoded === false ? '' : $encoded);
            return $response;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function checkDeleteAllForQueryStatus(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("Check delete all for query User personal api key");
        $span = $this->startSpan("Check delete all for query User personal api key");
        try {
            if (!isset($args['uid'])) {
                throw new NotFoundException('-');
            }
            $uid = $args['uid'];
            $info = $this->runner->detail(new TaskKey($uid));
            if (!$info) {
                throw new NotFoundException('-');
            }
            $encoded = json_encode($info);
            $response->getBody()->write($encoded === false ? '' : $encoded);
            return $response->withStatus(200)
              ->withHeader('Content-Type', 'application/json');
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
